154	    class WatcherWrapper
155	        : public SubchannelInterface::ConnectivityStateWatcherInterface {
156	     public:
157	      WatcherWrapper(std::unique_ptr<
158	                         SubchannelInterface::ConnectivityStateWatcherInterface>
159	                         watcher,
160	                     bool ejected)
161	          : watcher_(std::move(watcher)), ejected_(ejected) {}
162	
163	      void Eject() {
164	        ejected_ = true;
165	        if (last_seen_state_.has_value()) {
166	          watcher_->OnConnectivityStateChange(
167	              GRPC_CHANNEL_TRANSIENT_FAILURE,
168	              absl::UnavailableError(
169	                  "subchannel ejected by outlier detection"));
170	        }
171	      }
172	
173	      void Uneject() {
174	        ejected_ = false;
175	        if (last_seen_state_.has_value()) {
176	          watcher_->OnConnectivityStateChange(*last_seen_state_,
177	                                              last_seen_status_);
178	        }
179	      }
180	
181	      void OnConnectivityStateChange(grpc_connectivity_state new_state,
182	                                     absl::Status status) override {
183	        const bool send_update = !last_seen_state_.has_value() || !ejected_;
184	        last_seen_state_ = new_state;
185	        last_seen_status_ = status;
186	        if (send_update) {
187	          if (ejected_) {
188	            new_state = GRPC_CHANNEL_TRANSIENT_FAILURE;
189	            status = absl::UnavailableError(
190	                "subchannel ejected by outlier detection");
191	          }
192	          watcher_->OnConnectivityStateChange(new_state, status);
193	        }
194	      }
