605	  RefCountedPtr<LoadBalancingPolicy::SubchannelPicker>
606	  WaitForRoundRobinListChange(
607	      absl::Span<const absl::string_view> old_addresses,
608	      absl::Span<const absl::string_view> new_addresses,
609	      const std::map<UniqueTypeName, std::string> call_attributes = {},
610	      size_t num_iterations = 3, SourceLocation location = SourceLocation()) {
611	    gpr_log(GPR_INFO, "Waiting for expected RR addresses...");
612	    RefCountedPtr<LoadBalancingPolicy::SubchannelPicker> retval;
613	    size_t num_picks =
614	        std::max(new_addresses.size(), old_addresses.size()) * num_iterations;
615	    WaitForStateUpdate(
616	        [&](FakeHelper::StateUpdate update) {
617	          EXPECT_EQ(update.state, GRPC_CHANNEL_READY)
618	              << location.file() << ":" << location.line();
