624	          EXPECT_TRUE(picks.has_value())
625	              << location.file() << ":" << location.line();
626	          if (!picks.has_value()) return false;
627	          gpr_log(GPR_INFO, "PICKS: %s", absl::StrJoin(*picks, " ").c_str());
628	          // If the picks still match the old list, then keep going.
629	          if (PicksAreRoundRobin(old_addresses, *picks)) return true;
630	          // Otherwise, the picks should match the new list.
631	          bool matches = PicksAreRoundRobin(new_addresses, *picks);
632	          EXPECT_TRUE(matches)
633	              << "Expected: " << absl::StrJoin(new_addresses, ", ")
634	              << "\nActual: " << absl::StrJoin(*picks, ", ") << "\nat "
635	              << location.file() << ":" << location.line();
636	          if (matches) {
