void XdsOverrideHostLb::SubchannelWrapper::WatchConnectivityState(
    std::unique_ptr<ConnectivityStateWatcherInterface> watcher) {
  ConnectivityStateWatcherInterface* watcher_ptr = watcher.get();
  auto watcher_wrapper =
      std::make_unique<ConnectivityStateWatcher>(this, std::move(watcher));
  watchers_.emplace(watcher_ptr, watcher_wrapper.get());
  wrapped_subchannel()->WatchConnectivityState(std::move(watcher_wrapper));
}

void XdsOverrideHostLb::SubchannelWrapper::CancelConnectivityStateWatch(
    ConnectivityStateWatcherInterface* watcher) {
  auto it = watchers_.find(watcher);
  if (it == watchers_.end()) return;
  wrapped_subchannel()->CancelConnectivityStateWatch(it->second);
  watchers_.erase(it);
}

void XdsOverrideHostLb::SubchannelWrapper::UpdateConnectivityState(
    grpc_connectivity_state state) {
  grpc_connectivity_state previous_state =
      connectivity_state_.exchange(state, std::memory_order_relaxed);
  // When a tracked subchannel transitions to IDLE or TRANSIENT_FAILURE,
  // ask the channel to re-resolve so that we can pick up any changes to
  // the set of available hosts.  We only do this on an actual state
  // change, so that the initial state report (which always reports the
  // subchannel's starting state) does not trigger a re-resolution.
  if (previous_state != state &&
      (state == GRPC_CHANNEL_IDLE ||
       state == GRPC_CHANNEL_TRANSIENT_FAILURE)) {
    if (!policy_->shutting_down_) {
      if (GRPC_TRACE_FLAG_ENABLED(grpc_lb_xds_override_host_trace)) {
        gpr_log(GPR_INFO,
                "[xds_override_host_lb %p] subchannel wrapper %p reported "
                "state %s; requesting re-resolution",
                policy_.get(), this, ConnectivityStateName(state));
      }
      policy_->channel_control_helper()->RequestReresolution();
    }
  }
}

