XdsOverrideHostLb::SubchannelConnectionRequester::SubchannelConnectionRequester(
    RefCountedPtr<SubchannelWrapper> subchannel)
    : subchannel_(std::move(subchannel)) {
  GRPC_CLOSURE_INIT(&closure_, RunInExecCtx, this, nullptr);
  // Hop into the ExecCtx, so that we're not holding the data plane mutex
  // while we bounce onto the WorkSerializer to request the connection.
  ExecCtx::Run(DEBUG_LOCATION, &closure_, absl::OkStatus());
}

void XdsOverrideHostLb::SubchannelConnectionRequester::RunInExecCtx(
    void* arg, grpc_error_handle /*error*/) {
  auto* self = static_cast<SubchannelConnectionRequester*>(arg);
  self->subchannel_->policy()->work_serializer()->Run(
      [self]() {
        self->subchannel_->RequestConnection();
        delete self;
