300	LoadBalancingPolicy::PickResult XdsOverrideHostLb::Picker::Pick(
301	    LoadBalancingPolicy::PickArgs args) {
302	  auto* call_state = static_cast<LbCallStateInternal*>(args.call_state);
303	  auto override_host = call_state->GetCallAttribute(XdsHostOverrideTypeName());
304	  if (!override_host.empty()) {
305	    auto subchannel = policy_->LookupSubchannel(override_host);
306	    if (subchannel != nullptr) {
307	      // We have a subchannel for the requested override host.  How we
308	      // handle the pick depends on the subchannel's connectivity state.
309	      auto connectivity_state = subchannel->connectivity_state();
310	      if (connectivity_state == GRPC_CHANNEL_READY) {
311	        // Connected: route the pick to this subchannel.
312	        return PickResult::Complete(subchannel->wrapped_subchannel());
313	      } else if (connectivity_state == GRPC_CHANNEL_IDLE) {
314	        // Not connected yet: trigger a connection attempt and queue the
315	        // pick until the subchannel becomes connected.  The requester
316	        // deletes itself once it has requested the connection.
317	        new SubchannelConnectionRequester(std::move(subchannel));
318	        return PickResult::Queue();
319	      } else if (connectivity_state == GRPC_CHANNEL_CONNECTING) {
320	        // Connection in progress: queue the pick.
321	        return PickResult::Queue();
322	      }
323	      // In TRANSIENT_FAILURE (or SHUTDOWN), we do not honor the override.
324	      // Instead, we fall through to the child picker, which will use one
325	      // of the remaining ready subchannels.
326	    }
327	  }
328	  if (picker_ == nullptr) {  // Should never happen.
329	    return PickResult::Fail(absl::InternalError(
330	        "xds_override_host picker not given any child picker"));
331	  }
332	  auto result = picker_->Pick(args);
333	  auto complete_pick = absl::get_if<PickResult::Complete>(&result.result);
334	  if (complete_pick != nullptr) {
335	    complete_pick->subchannel =
336	        static_cast<SubchannelWrapper*>(complete_pick->subchannel.get())
337	            ->wrapped_subchannel();
338	  }
339	  return result;
340	}
