598	void XdsOverrideHostLb::SubchannelWrapper::UpdateConnectivityState(
599	    grpc_connectivity_state state) {
600	  grpc_connectivity_state previous_state =
601	      connectivity_state_.exchange(state, std::memory_order_relaxed);
602	  // When a tracked subchannel transitions to IDLE or TRANSIENT_FAILURE,
603	  // ask the channel to re-resolve so that we can pick up any changes to
604	  // the set of available hosts.  We only do this on an actual state
605	  // change, so that the initial state report (which always reports the
606	  // subchannel's starting state) does not trigger a re-resolution.
607	  if (previous_state != state &&
608	      (state == GRPC_CHANNEL_IDLE ||
609	       state == GRPC_CHANNEL_TRANSIENT_FAILURE)) {
610	    if (!policy_->shutting_down_) {
611	      if (GRPC_TRACE_FLAG_ENABLED(grpc_lb_xds_override_host_trace)) {
612	        gpr_log(GPR_INFO,
613	                "[xds_override_host_lb %p] subchannel wrapper %p reported "
614	                "state %s; requesting re-resolution",
615	                policy_.get(), this, ConnectivityStateName(state));
616	      }
617	      policy_->channel_control_helper()->RequestReresolution();
618	    }
619	  }
620	}
